window.RP_SESSION={"id":"S-9fe18be02a0b","messages":[{"id":"RP-0298869","time":"2026-09-24T01:08:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"덜덜덜덜덜덜","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298870","time":"2026-09-24T01:09:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 귀족의 거리 한 구석에 위치한 카페 구석진 룸 안에서 다리를 떨면서 기다리고 있었다. 앞에 쌓여있는 찻잔만 벌써 세잔.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298871","time":"2026-09-24T01:09:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"길란, 그 녀석은 언제 오는거람?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298872","time":"2026-09-24T01:10:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"그래도 지금은 조금 나은 편이다. 한 때는 카페 한 가운데서 이렇게 기다리고 있느라 눈치를 많이 보고 있었으니까.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298873","time":"2026-09-24T01:10:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"골기아가 [비교적] 차별이 적은 곳이지 차별이 없는 곳은 아닌데다 이런 귀족들이나 나들이할만한 거리에 있는 너저분한 드라고니안 한명.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298874","time":"2026-09-24T01:10:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"어떻게든 후드를 뒤집어 쓴 채로 피에르마냥 구부정하게 있던 그 부담스러운 나날이여.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298875","time":"2026-09-24T01:11:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"똑똑똑.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298876","time":"2026-09-24T01:11:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"순간 문이 두들기는 소리가 들린다.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298877","time":"2026-09-24T01:12:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"들어와, 벌써 홍차, 커피, 과실차 한잔씩이나 마신 상태라고.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298878","time":"2026-09-24T01:12:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"들어가지.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298879","time":"2026-09-24T01:12:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"문이 열리자 들어온 사람은 라운데라 성기사 복장의 사내였다.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298880","time":"2026-09-24T01:12:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298881","time":"2026-09-24T01:13:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"이봐, 길란. 네가 아무리 라운데라 교단 성기사고 나는 별 것 없는 모험가라지만 이렇게 매번 기다리게 하면 곤란해.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298882","time":"2026-09-24T01:13:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"사과하겠다.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298883","time":"2026-09-24T01:13:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"길란은 순순히 고개를 숙이며 사과하고서 아카쿠의 앞에 앉았다.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298884","time":"2026-09-24T01:14:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"자, 일부터 할게. 시장 드라고니안이나 서부 출신 친구들 중 딱히 집회나 집단을 꾸리려는 녀석들은 없었어. 전도를 시도하는 사람도 없었고 말이야.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298885","time":"2026-09-24T01:14:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그렇군. 알았다.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298886","time":"2026-09-24T01:15:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"얼라리? 그냥 그렇게 넘어가는거야? 이유는 안 물어보고?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298887","time":"2026-09-24T01:15:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"슬슬 믿어도 된다고 생각하니까.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298888","time":"2026-09-24T01:15:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 짜게 식은 눈으로 길란을 바라보면서 차를 다시 호로록 들이켰다.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298889","time":"2026-09-24T01:16:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"나 참. 그 때랑 같은 사람인지 도통 모르겠네.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298890","time":"2026-09-24T01:16:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"무슨 소리인가?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298891","time":"2026-09-24T01:17:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"처음 레난 상회의 집사가 노환으로 상태가 안 좋아서 봐주던 때 갑자기 들이닥쳐서...! 이교도 행위를 이용하여 질서를 어지른 죄를 묻겠다! 라면서 포승줄에 끌려가던 때가 한달 조금 더 지났거든?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298892","time":"2026-09-24T01:18:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그건 자네도 이해할만한 이야기 아닌가?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298893","time":"2026-09-24T01:18:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭐... 그렇긴 하다만...\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298894","time":"2026-09-24T01:18:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"라운데라 교리가 국교인 지역에서 다른 종교의 사제가 치료 행위를 하는 것은 그 종교의 권리에 대한 도전이다.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298895","time":"2026-09-24T01:18:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그래 뭐... 내가 좀 더 조심했어야 했는데.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298896","time":"2026-09-24T01:20:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아, 물론 들키지 않았어야 했는데라는 이야기야.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298897","time":"2026-09-24T01:20:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"나름 쏠쏠한 벌이였는데 말이야~\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298898","time":"2026-09-24T01:20:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"칵칵칵!\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298899","time":"2026-09-24T01:21:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298900","time":"2026-09-24T01:21:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"칵칵!\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298901","time":"2026-09-24T01:21:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298902","time":"2026-09-24T01:21:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"응? 왜 그렇게 보고 있어?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298903","time":"2026-09-24T01:23:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"길란은 조금 고민하다가 입을 열었다.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298904","time":"2026-09-24T01:23:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"너는, 이대로 괜찮은가?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298905","time":"2026-09-24T01:23:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"응? 갑자기 무슨 소리야?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298906","time":"2026-09-24T01:23:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"지금 하는 행위가 너의 동족과 종교에 대한 스파이 행위가 아니냐는 이야기다.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298907","time":"2026-09-24T01:24:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 길란의 이야기를 듣고서 웃음기를 거두고서 잠시 생각하더니...","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298908","time":"2026-09-24T01:24:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭐, 아무렇지 않다고 하면 조금 씁쓸하기는 하지.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298909","time":"2026-09-24T01:25:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그래도 말이야. 여기는 스카일라도 서부도 아니잖아.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298910","time":"2026-09-24T01:25:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"다른 곳에 왔으면 다른 곳의 문화를 따르는게 맞아.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298911","time":"2026-09-24T01:26:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"솔직히 말해서 나는 골기아에서 라운데라 교리가 아닌 타 종교에 대해서 권유, 포교, 혹은 집회를 가지지 않으면 넘어가는 것도 좀 신기하다고 생각하고 있어.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298912","time":"2026-09-24T01:26:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"스카일라나 로운델같은 종교 중심 국가면 바로 몰매를 맞을지도 모를 일이니까 말이야.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298913","time":"2026-09-24T01:26:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 접시에 있는 쿠키를 두어개 집어먹고서 차를 마시고서 말을 이어갑니다.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298914","time":"2026-09-24T01:28:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"이렇게 라운데라 교단에게 감시를 받을 것도 알고는 있었고.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298915","time":"2026-09-24T01:28:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그건 처음 듣는 이야기인데.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298916","time":"2026-09-24T01:29:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"슬쩍 치료인데 치료아닌 것 같은 행위로 사람들에게서 돈을 뜯어내는게 너희를 부르기 위함이었다고.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298917","time":"2026-09-24T01:29:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"...?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298918","time":"2026-09-24T01:30:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그러니까! 너희도 알 것 아니야. 내가 골기아에 올 때, 라이아흐 가문 출신의 사람이 골기아에서 살기를 원한다고 다 들었을 것 아니야?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298919","time":"2026-09-24T01:30:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"물론 그랬을 것이다.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298920","time":"2026-09-24T01:30:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그러면 내가 찾아가서 나 카카투 교단이며 스카일라 귀족인데 감시하세요~ 하고 찾아가리?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298921","time":"2026-09-24T01:31:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"이해했다.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298922","time":"2026-09-24T01:31:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭐, 그렇게 넘어가면 좋고.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298923","time":"2026-09-24T01:32:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 그렇게 말하고서 이에 낀 쿠키를 살살 긁어내고 있을 때 길란이 입을 열었다.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298924","time":"2026-09-24T01:34:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"조금 더 현명한 방법은 없었나? 결국 연행당하는 것 자체가 좋은 방법은 아니지 않나?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298925","time":"2026-09-24T01:34:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아, 그건 이유가 있어.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298926","time":"2026-09-24T01:34:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭔가?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298927","time":"2026-09-24T01:34:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"한탕 땡기는거지 뭐. 타국 생활 해야하는데 이만큼 쏠쏠한게 어디 있겠어? 지금 아니면 못 할 것 같았지. 칵칵칵!\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298928","time":"2026-09-24T01:35:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"길란은 한숨을 푹 쉬고서 역시나 네가 그렇지 라는 표정을 지었다.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298929","time":"2026-09-24T01:35:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그나저나 그 질문은 안 대답하지 않았나?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298930","time":"2026-09-24T01:35:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭐가 말이야?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298931","time":"2026-09-24T01:35:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"스파이 행위에 대한 이야기.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298932","time":"2026-09-24T01:36:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"으음... 그걸로 대답이 안된거라면...\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298933","time":"2026-09-24T01:36:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그 왜, 내가 처음 골기아에 왔을 때 느낀게 있는데 말이야.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298934","time":"2026-09-24T01:36:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"사람들이 드라고니안이라는 종족을 엄청 싫어하더라고.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298935","time":"2026-09-24T01:36:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아무래도 친숙한 얼굴은 아니니까.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298936","time":"2026-09-24T01:36:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"나도 아네요!\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298937","time":"2026-09-24T01:36:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 흠흠 목을 다시 가다듬고서.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298938","time":"2026-09-24T01:37:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"이게 다~ 선입견이란 말이지. 무섭게 생겼다고 성격도 이상하고 잘 못 지낼거라고 생각하고 말이야.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298939","time":"2026-09-24T01:37:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그게 어쨌다는건가?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298940","time":"2026-09-24T01:37:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아, 너무 빙빙 돌고있네.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298941","time":"2026-09-24T01:37:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"요컨데 모두와 잘 지낼 필요가 있다는거야.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298942","time":"2026-09-24T01:38:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"...?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298943","time":"2026-09-24T01:38:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"왜 이리 오늘따라 말을 못 알아듣는담?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298944","time":"2026-09-24T01:40:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"주로 인간이지만.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298945","time":"2026-09-24T01:40:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"골기아에는 생각보다 많은 집단들이 있단 말이지.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298946","time":"2026-09-24T01:40:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"인간, 드워프, 엘프, 데미간. 아, 티플링이랑 오니는 없더라.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298947","time":"2026-09-24T01:41:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"어쨌든 그들은 각자 이 곳에서 각자의 문화로 뿌리와 자리를 잡은 상태라는 이야기야.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298948","time":"2026-09-24T01:41:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"굳이 긁어부스럼 만들지 않고 적당히 잘 녹아들면서 지내는게 중요하다고.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298949","time":"2026-09-24T01:42:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"카카투 신앙이나 집회같은게 열리는 것 자체가 그것에 반하는 행위니까 이 부분을 피하는게 나의 동료, 종교, 그리고 나의 가족들에게도 좋다는 이야기지.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298950","time":"2026-09-24T01:42:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"즉, 눈칫밥먹고 있다는 건가?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298951","time":"2026-09-24T01:42:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그래! 짜샤! 그냥 친구먹으면 편하다는 생각도 매번 하기는 하지만 어떤 친구를 사귀는게 좋은지는 생각을 해야한다는 말이야.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298952","time":"2026-09-24T01:43:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"필요에 의해서 친해질 필요가 있는 사람들도 있다고.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298953","time":"2026-09-24T01:43:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"참으로 어렵게 사는데.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298954","time":"2026-09-24T01:43:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭐, 어쩌겠어. 여기는 스카일라가 아닌데. 나의 아내 미샤도 스카일라에서 이렇게 살았을텐데.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298955","time":"2026-09-24T01:43:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"이번에는 내 차례인거지.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298956","time":"2026-09-24T01:44:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 마시던 차를 끝까지 입에 털어놓고서.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298957","time":"2026-09-24T01:44:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"아차! 하는 얼굴을 하고서 입을 열었다.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298958","time":"2026-09-24T01:45:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아, 음... 너무 섭섭한 이야기인가?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298959","time":"2026-09-24T01:45:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그 왜, 너랑 친해진 것도 계산적인 것처럼 들렸을 것 같은데 꼭 그런게 아니라...\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298960","time":"2026-09-24T01:45:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아니, 무슨 말인지 알았다.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298961","time":"2026-09-24T01:46:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"길란은 아카쿠의 말을 끊고서 말을 이어갔다.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298962","time":"2026-09-24T01:46:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"네가 나쁜 녀석은 아니라는 것은 알고 있으니 말이다.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298963","time":"2026-09-24T01:46:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭐... 그렇담 다행이고.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298964","time":"2026-09-24T01:47:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"멋쩍은지 얼굴을 긁쩍~","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298965","time":"2026-09-24T01:47:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"저기 길란, 이렇게 다 말했는데 나도 뭐 하나 물어봐도 될까?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298966","time":"2026-09-24T01:47:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"무슨 일인가?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298967","time":"2026-09-24T01:47:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그 왜, 요즘 사자회가 좀 뒤숭숭해 보이는데... 이야기 들은게 없어? 그 뭐시다냐... 아는 형님이 있는데 요즘 보기 힘들어서 말이지.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298968","time":"2026-09-24T01:48:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"길란은 아카쿠의 얼굴을 보고서. 잠시 고민을 하더니.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298969","time":"2026-09-24T01:48:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"미안하다. 말하기 힘들 것 같다.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298970","time":"2026-09-24T01:48:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭐, 별 수 없지. 그런가? 그럼 뭐...\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298971","time":"2026-09-24T01:48:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"우리 용건 끝난거지? 나 좀 알아봐야할게 있어서 먼저 가볼게?\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298972","time":"2026-09-24T01:48:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그래.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298973","time":"2026-09-24T01:49:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 후드를 얼굴 끝까지 가린 뒤에 카페의 개인실에서 나오려다가...!","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298974","time":"2026-09-24T01:49:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아, 기다리게 했으니까 찻값은 네가 내는거다.\"","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298975","time":"2026-09-24T01:49:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"하고서 쌩! 하고 사라졌다.","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298976","time":"2026-09-24T01:49:00+09:00","room":"RP","name":"아카쿠 / 길란","profile":"GM","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-96ab98d2591c","P-bd6abb25f638"]},{"id":"RP-0298977","time":"2026-09-24T01:49:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]},{"id":"RP-0298978","time":"2026-09-24T02:41:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"unresolved","type":"dialogue","body":"!모닥불","characters":[]},{"id":"RP-0298979","time":"2026-09-24T02:41:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]}]};
